head.script:
scwin.onpageload = function () {

};

scwin.trigger1_onclick = function (e) {
    input1.addClass("req");
};

scwin.trigger2_onclick = function (e) {
    input1.addClass("req error");
};

scwin.trigger3_onclick = function (e) {
    input1.addClass("req error test");
};

scwin.trigger4_onclick = function (e) {
    input1.removeClass("req");
};

scwin.trigger5_onclick = function (e) {
    input1.removeClass("error");
};

scwin.trigger6_onclick = function (e) {
    input1.removeClass("test");
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('input1').classList.value.indexOf('w2input req error') != -1;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('input1').classList.value.indexOf('w2input error') != -1;
	}	
	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "400");	



		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
